        :return: None. There are no return values.

        """
        if not state_dict:
            print("The state dictionary is empty. The state of the CombinedStreamingDataset and its constituent datasets will not be modified.")
            return

        if len(state_dict["dataset"]) != len(self._datasets):
            print(
                f"The number of datasets in the state dictionary ({len(state_dict['dataset'])}) does not match the number of datasets in the CombinedStreamingDataset object ({len(self._datasets)}). The state of the CombinedStreamingDataset and its constituent datasets will not be modified."
            )
            return

        for i, dataset in enumerate(self._datasets):
            if i not in state_dict["dataset"]:
                print(
                    f"The state of the dataset with index {i} will not be modified. The state of the CombinedStreamingDataset and its constituent datasets will still be restored with the available states."
                )
                continue

            dataset.load_state_dict(state_dict["dataset"][i])

        if "num_samples_yielded" in state_dict:
            self.num_samples_yielded = state_dict["num_samples_yielded"]
