        if node_rank != 0 and self._distributed_env:
            while True:
                if os.path.exists(os.path.join(self._cache_dir, self._INDEX_FILENAME)):
                    break

        if self._distributed_env and node_rank == 0:
            worker_files = glob.glob(os.path.join(self._cache_dir, '*'))
            while len(worker_files) < num_workers:
                worker_files = glob.glob(os.path.join(self._cache_dir, '*'))

            index_files = [f for f in worker_files if os.path.getsize(f) > 0]
            if len(index_files) == num_workers:
                with open(os.path.join(self._cache_dir, self._INDEX_FILENAME), 'wb') as merged_index:
                    for file in index_files:
                        with open(file, 'rb') as f:
                            merged_index.write(f.read())
                        os.remove(file)
