def generate_safe_fn(fn, input_range, grad_fn=None):
  """
  Generates a safe version of the given function with the specified input range.
  """

  def safe_fn(x):
    if not isinstance(x, jnp.ndarray):
      x = jnp.asarray(x)
    if jnp.isscalar(x):
      if x < input_range[0] or x > input_range[1]:
        return jnp.nan
      else:
