      return jnp.where(jnp.logical_or(x < input_range[0], x > input_range[1]), jnp.nan, fn(clipped))

  if grad_fn is None:
    grad_fn = lambda x: fn(x)

  def safe_grad_fn(x):
    return grad_fn(safe_fn(x))

  return safe_fn, safe_grad_fn

