from jax import custom_gradient

@custom_gradient
def generate_safe_fn(f, safe_range, grad_fn):
  """
  The helper function creates a custom gradient version of the input function `f`, ensuring that the input values are within the specified safe range. It also provides a custom gradient function for backpropagation.

  Input-Output Arguments
  :param f: The input function for which the safe version is created.
  :param safe_range: A tuple containing the lower and upper bounds for the input values.
  :param grad_fn: The gradient function associated with the input function `f`.
  :return: The custom gradient function that applies the input function `f` with safety checks and uses the custom gradient function for backpropagation.
  """
  def safe_fn(x):
    if not (-jnp.inf <= x).all() or not (x <= jnp.inf).all():
      raise ValueError("Input values must be finite.")
